import * as T from 'three/tsl';
export function attachAdvancedShading(material,values){
 const setup=material.setupLightingModel.bind(material);material.setupLightingModel=builder=>{const model=setup(builder),direct=model.direct.bind(model);model.direct=(data,builder)=>{const before=data.reflectedLight.directDiffuse.toVar();direct(data,builder);const n=T.normalView,v=T.positionViewDirection,l=data.lightDirection,nl=n.dot(l),skin=values.subsurface.clamp(0,1),foliage=values.foliage.clamp(0,1),hair=values.hair.clamp(0,1),tint=values.subsurfaceColor.clamp(0,1),thickness=values.subsurfaceThickness.max(0),wrap=nl.add(.5).div(1.5).max(0),back=l.negate().dot(v).max(0).pow(4).mul(thickness.negate().exp()),diffuse=T.diffuseColor.rgb;
  T.If(skin.greaterThan(0).or(foliage.greaterThan(0)),()=>{data.reflectedLight.directDiffuse.assign(T.mix(data.reflectedLight.directDiffuse,before,skin));data.reflectedLight.directDiffuse.addAssign(data.lightColor.mul(diffuse).mul(tint).mul(skin.mul(wrap.add(back)).add(foliage.mul(nl.negate().max(0)))).mul(.318309886));});
  T.If(hair.greaterThan(0),()=>{const safe=a=>a.mul(a.dot(a).max(.000001).inverseSqrt()),axis=values.hairTangent.transformDirection(T.cameraViewMatrix),fallback=n.cross(n.z.abs().lessThan(.9).select(T.vec3(0,0,1),T.vec3(0,1,0))),tangent=axis.dot(axis).lessThan(.000001).select(fallback,axis),shift=values.hairShift,h=safe(v.add(l)),t1=safe(tangent.add(n.mul(shift))),t2=safe(tangent.sub(n.mul(shift.add(.3)))),exponent=T.float(2).div(T.roughness.mul(T.roughness).max(.001)).sub(2).clamp(1,2048),a=T.float(1).sub(t1.dot(h).pow(2)).max(0).sqrt(),b=T.float(1).sub(t2.dot(h).pow(2)).max(0).sqrt(),direction=nl.max(0).add(nl.negate().max(0).mul(.25));data.reflectedLight.directSpecular.addAssign(data.lightColor.mul(T.vec3(.04).mul(a.pow(exponent)).add(diffuse.mul(.12).mul(b.pow(exponent.mul(.5))))).mul(exponent.add(2).mul(.159154943)).mul(direction).mul(hair));});};return model;};
}
